          "id": "B",
          "text": "The difference has last digit 1.",
          "figure_ids": []
        },
        {
          "id": "C",
          "text": "The product from 7 through 81 has last digit 0.",
          "figure_ids": []
        },
        {
          "id": "D",
          "text": "The sum of all three-digit numbers has last digit 0.",
